options.getOption:
// The whole forecast over the drawn area: the mean as a thick line, the band
// between the minimum and the maximum behind it. The step the map is drawing
// is the dashed vertical line.
//
// Clicking anywhere on the chart picks the nearest forecast step: it writes
// `hora`, the hour the map follows, and the map's own window with it, so the
// map and the three figures move to that hour. There is nothing to clear: the
// map always draws one hour.

// @constants begin
const HOUR_VAR = 'hora'; // the variable the map and the figures follow
const FROM_VAR = 'mapFrom'; // the map's window, written with it
const TO_VAR = 'mapTo';
const WINDOW_MS = 6 * 3600 * 1000; // mapFrom = hora - 6 h, as the variable query does
// written out, not built from the name: a variable spelled in the code is what
// makes Grafana redraw the chart when it changes, with no query re-run
const DRAWN = '${horaDibujada}'; // the exact step the map is drawing
const LABEL = '${variable:text}'; // "2 m temperature (C)": the unit is in brackets
const COLOR_MEAN = 'green';
const COLOR_MIN = 'blue';
const COLOR_MAX = 'orange';
// @constants end

const chart = context.panel.chart;
const grafana = context.grafana;
const theme = grafana.theme;
const muted = theme.colors.text.secondary;
const color = (name) => theme.visualization.getColorByName(name);

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const num = (v) => (v == null || v === '' ? null : Number(v));
const times = col('time').map(Number);
const mean = col('mean').map(num);
const min = col('min').map(num);
const max = col('max').map(num);

const label = grafana.replaceVariables(LABEL);
const unit = (label.match(/\(([^)]*)\)\s*$/) || [])[1] || '';
const drawn = Date.parse(grafana.replaceVariables(DRAWN));
const fmt = (v) => (v == null ? '–' : Math.abs(v) >= 1000 ? v.toFixed(0) : Math.abs(v) < 0.01 ? v.toExponential(2) : v.toFixed(1));
const when = (ms) => new Date(ms).toISOString().slice(5, 16).replace('T', ' ') + ' UTC';

// The nearest step to a pixel on the x axis.
const nearest = (ms) => {
  let best = -1;
  let gap = Infinity;
  times.forEach((t, i) => {
    if (Math.abs(t - ms) < gap) {
      gap = Math.abs(t - ms);
      best = i;
    }
  });
  return best;
};

const zr = chart.getZr();
zr.off('click');
zr.on('click', (e) => {
  if (!times.length || !chart.containPixel({ gridIndex: 0 }, [e.offsetX, e.offsetY])) {
    return;
  }
  const i = nearest(chart.convertFromPixel({ gridIndex: 0 }, [e.offsetX, e.offsetY])[0]);
  if (i < 0) {
    return;
  }
  const iso = new Date(times[i]).toISOString();
  grafana.locationService.partial(
    {
      ['var-' + HOUR_VAR]: iso,
      ['var-' + FROM_VAR]: new Date(times[i] - WINDOW_MS).toISOString(),
      ['var-' + TO_VAR]: iso,
    },
    true
  );
});

const di = Number.isFinite(drawn) ? times.indexOf(drawn) : -1;

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 24, top: 40, bottom: 8, containLabel: true },
  legend: {
    top: 0,
    right: 8,
    textStyle: { color: muted },
    data: ['mean', 'min', 'max'],
    selectedMode: false,
  },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'line' },
    formatter: (items) => {
      const i = items[0].dataIndex;
      return (
        `<b>${when(times[i])}</b><br/>` +
        `mean <b>${fmt(mean[i])} ${unit}</b><br/>min ${fmt(min[i])} · max ${fmt(max[i])} ${unit}` +
        `<br/><span style="opacity:.7">click to draw this hour on the map</span>`
      );
    },
  },
  xAxis: {
    type: 'time',
    axisLabel: { color: muted, hideOverlap: true },
    axisLine: { lineStyle: { color: theme.colors.border.weak } },
    splitLine: { show: false },
  },
  yAxis: {
    type: 'value',
    scale: true,
    name: unit,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted },
    splitLine: { lineStyle: { color: theme.colors.border.weak } },
  },
  series: [
    // The band: an invisible base at the minimum, the range stacked on it.
    {
      name: 'band-base',
      type: 'line',
      stack: 'band',
      symbol: 'none',
      silent: true,
      lineStyle: { opacity: 0 },
      tooltip: { show: false },
      data: times.map((t, i) => [t, min[i]]),
    },
    {
      name: 'band',
      type: 'line',
      stack: 'band',
      symbol: 'none',
      silent: true,
      lineStyle: { opacity: 0 },
      areaStyle: { color: 'rgba(128,128,128,0.22)' },
      tooltip: { show: false },
      data: times.map((t, i) => [t, max[i] == null || min[i] == null ? null : max[i] - min[i]]),
    },
    {
      name: 'min',
      type: 'line',
      symbol: 'none',
      lineStyle: { width: 1, color: color(COLOR_MIN) },
      itemStyle: { color: color(COLOR_MIN) },
      data: times.map((t, i) => [t, min[i]]),
    },
    {
      name: 'max',
      type: 'line',
      symbol: 'none',
      lineStyle: { width: 1, color: color(COLOR_MAX) },
      itemStyle: { color: color(COLOR_MAX) },
      data: times.map((t, i) => [t, max[i]]),
    },
    {
      name: 'mean',
      type: 'line',
      symbol: 'none',
      lineStyle: { width: 3, color: color(COLOR_MEAN) },
      itemStyle: { color: color(COLOR_MEAN) },
      data: times.map((t, i) => [t, mean[i]]),
      markLine:
        di < 0
          ? undefined
          : {
              silent: true,
              symbol: 'none',
              lineStyle: { type: 'dashed', color: theme.colors.text.primary, width: 1.5 },
              label: { formatter: 'on the map · ' + when(drawn), color: theme.colors.text.primary, position: 'end', distance: 2 },
              data: [{ xAxis: drawn }],
            },
      markPoint:
        di < 0 || mean[di] == null
          ? undefined
          : {
              silent: true,
              symbol: 'circle',
              symbolSize: 10,
              itemStyle: { color: color(COLOR_MEAN), borderColor: theme.colors.text.primary, borderWidth: 2 },
              label: { show: false },
              data: [{ coord: [drawn, mean[di]] }],
            },
    },
  ],
};
